FUNC-MERDIAN-SURFACE:
def classify_surface(homepage, sections, contact_api):
    required = {"Consultancy", "Laboratory", "Ventures"}
    if not isinstance(homepage, str) or "INTELLIGENCE, MADE REAL." not in homepage or not required.issubset(set(sections)):
        return "DESIGN_REGRESSION"
    if not isinstance(contact_api, dict) or type(contact_api.get("acceptingEnquiries")) is not bool:
        return "ENQUIRIES_UNKNOWN"
    return "ENQUIRIES_OPEN" if contact_api["acceptingEnquiries"] else "ENQUIRIES_DISABLED"

FUNC-INTENT-AUTHORITY:
def choose_intent(requested, registry, retrieved_memory):
    if isinstance(requested, str) and bool(requested) and isinstance(registry, dict) and registry.get(requested) is True:
        return requested
    return "DENY"

FUNC-FLOW-YIELD:
def classify_delivery(record):
    if not isinstance(record, dict) or record.get("committed") is not True:
        return "NO_EVIDENCE"
    if record.get("deployed") is not True:
        return "COMMITTED_ONLY"
    if all(record.get(field) is True for field in ("verified","real_caller_passed","revision_matches")):
        return "VERIFIED_YIELD"
    return "DEPLOYED_UNVERIFIED"
